    <style>
        :root{--bg:#0c0e10;--panel:#171b20;--text:#f4f6f8;--muted:#a8b0ba;--line:rgba(255,255,255,.09);--gold:#f5c84c;--max:1160px}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 82% 5%,rgba(245,200,76,.11),transparent 28rem),radial-gradient(circle at 8% 38%,rgba(245,200,76,.055),transparent 22rem),var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;line-height:1.6}a{color:inherit;text-decoration:none}.wrap{width:min(calc(100% - 36px),var(--max));margin-inline:auto}.nav{position:sticky;top:0;z-index:20;backdrop-filter:blur(16px);background:rgba(12,14,16,.78);border-bottom:1px solid var(--line)}.nav-inner{height:74px;display:flex;align-items:center;justify-content:space-between;gap:28px}.brand{display:flex;align-items:center;gap:11px;font-weight:850}.brand-mark{display:grid;place-items:center;width:38px;height:38px;border-radius:11px;color:#161616;background:linear-gradient(145deg,#ffe483,var(--gold));box-shadow:0 7px 22px rgba(245,200,76,.18)}.brand small{display:block;color:var(--muted);font-size:10px;letter-spacing:.16em;text-transform:uppercase}.links{display:flex;align-items:center;gap:26px;color:#c9ced4;font-size:14px}.nav-cta{padding:10px 16px;border-radius:10px;background:var(--gold);color:#111;font-weight:800}.hero{padding:92px 0 72px}.hero-grid{display:grid;grid-template-columns:1.12fr .88fr;gap:64px;align-items:center}.eyebrow{display:inline-flex;align-items:center;gap:9px;color:#f8d868;font-size:13px;font-weight:750;letter-spacing:.08em;text-transform:uppercase}.eyebrow:before{content:"";width:24px;height:2px;background:var(--gold)}h1{margin:17px 0 20px;font-size:clamp(42px,6.2vw,76px);line-height:.98;letter-spacing:-.055em}.gold{color:var(--gold)}.lead{max-width:640px;margin:0;color:#b9c0c8;font-size:clamp(17px,2vw,20px)}.hero-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:32px}.btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;min-height:48px;padding:0 20px;border-radius:11px;font-weight:800;border:1px solid transparent}.btn-primary{background:var(--gold);color:#101010}.btn-secondary{border-color:var(--line);background:rgba(255,255,255,.035)}.micro{margin-top:20px;color:#7f8993;font-size:13px}.device-card{position:relative;min-height:445px;border:1px solid var(--line);border-radius:28px;background:linear-gradient(145deg,rgba(255,255,255,.055),rgba(255,255,255,.018));overflow:hidden;box-shadow:0 30px 100px rgba(0,0,0,.34)}.board{position:absolute;inset:56px 42px;border:1px solid rgba(245,200,76,.22);border-radius:20px;background:#111419;transform:rotate(-3deg)}.trace{position:absolute;background:rgba(245,200,76,.28)}.t1{width:55%;height:2px;left:14%;top:25%}.t2{width:2px;height:42%;left:36%;top:25%}.t3{width:43%;height:2px;left:36%;top:66%}.chip{position:absolute;left:48%;top:39%;width:92px;height:72px;border:1px solid rgba(255,255,255,.12);border-radius:10px;background:#232830}.meter{position:absolute;right:28px;top:25px;padding:11px 13px;border-radius:12px;background:var(--gold);color:#131313;font-weight:900;font-size:13px}.status{position:absolute;left:26px;bottom:24px;padding:10px 13px;border-radius:12px;background:rgba(13,16,19,.82);border:1px solid var(--line);font-size:13px}.trust{border-block:1px solid var(--line);background:rgba(255,255,255,.018)}.trust-inner{min-height:82px;display:grid;grid-template-columns:repeat(4,1fr);align-items:center}.trust-item{padding:8px 22px;border-right:1px solid var(--line)}.trust-item:first-child{padding-left:0}.trust-item:last-child{border:0}.trust-item strong{display:block;font-size:15px}.trust-item span{color:#7f8993;font-size:12px}section{padding:88px 0}.section-head{display:flex;justify-content:space-between;gap:40px;align-items:end;margin-bottom:34px}.section-head h2,.split h2,.contact-box h2{margin:8px 0 0;font-size:clamp(31px,4vw,48px);line-height:1.05;letter-spacing:-.04em}.section-head p,.split p,.contact-box p{max-width:520px;color:var(--muted)}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{padding:28px;border:1px solid var(--line);border-radius:18px;background:linear-gradient(155deg,rgba(255,255,255,.047),rgba(255,255,255,.018));min-height:250px}.icon{display:grid;place-items:center;width:44px;height:44px;margin-bottom:48px;border-radius:12px;background:rgba(245,200,76,.1);color:var(--gold);border:1px solid rgba(245,200,76,.16)}.card h3{margin:0 0 8px;font-size:21px}.card p{margin:0;color:var(--muted);font-size:14px}.dark-band{background:#0a0c0e;border-block:1px solid var(--line)}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:36px;counter-reset:step}.step{counter-increment:step}.step:before{content:"0" counter(step);display:block;color:var(--gold);font-size:13px;font-weight:900;margin-bottom:16px}.step h3{margin:0 0 8px}.step p{margin:0;color:var(--muted);font-size:14px}.split{display:grid;grid-template-columns:.86fr 1.14fr;gap:70px}.list{display:grid;gap:12px}.list-item{display:flex;gap:13px;padding:18px;border:1px solid var(--line);border-radius:14px;background:rgba(255,255,255,.025)}.tick{color:var(--gold);font-weight:900}.list-item strong{display:block}.list-item span{color:var(--muted);font-size:13px}.contact-box{display:grid;grid-template-columns:.9fr 1.1fr;gap:52px;padding:48px;border-radius:24px;background:linear-gradient(135deg,#1d2024,#121518);border:1px solid var(--line)}form{display:grid;gap:12px}.field{width:100%;border:1px solid var(--line);background:#0d1013;color:white;border-radius:11px;padding:13px 14px}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:12px}textarea.field{min-height:130px}.note{color:#6f7881;font-size:12px}footer{padding:28px 0 42px;color:#7d858e;font-size:13px}.footer-inner{display:flex;justify-content:space-between;gap:20px;padding-top:25px;border-top:1px solid var(--line)}@media(max-width:900px){.links a:not(.nav-cta){display:none}.hero-grid,.split,.contact-box{grid-template-columns:1fr}.trust-inner{grid-template-columns:1fr 1fr}.cards,.steps{grid-template-columns:1fr}.section-head{align-items:start;flex-direction:column}.contact-box{padding:30px}}@media(max-width:560px){.wrap{width:min(calc(100% - 24px),var(--max))}.brand small{display:none}h1{font-size:46px}.form-row,.trust-inner{grid-template-columns:1fr}.footer-inner{flex-direction:column}}
    </style>
</head>
<body>
<nav class="nav"><div class="wrap nav-inner"><a class="brand" href="#top"><span class="brand-mark">⚡</span><span>Zlatý technik<small>opravy • IT • technika</small></span></a><div class="links"><a href="#sluzby">Služby</a><a href="#ako">Ako to funguje</a><a href="#pristup">Prístup</a><a class="nav-cta" href="#kontakt">Kontakt</a></div></div></nav>
<main id="top">
<header class="hero"><div class="wrap hero-grid"><div><div class="eyebrow">Zvolen a okolie</div><h1>Pokazené nemusí znamenať <span class="gold">na odpis.</span></h1><p class="lead">Opravy elektroniky, technická pomoc, weby a malé IoT riešenia. Najprv zistíme, či sa problém oplatí riešiť — bez zbytočného menenia dielov a nákladov.</p><div class="hero-actions"><a class="btn btn-primary" href="#kontakt">Mám pokazené zariadenie →</a><a class="btn btn-secondary" href="#sluzby">Pozrieť služby</a></div><p class="micro">Pošli fotku a stručný popis problému. Povieme si, či má diagnostika zmysel.</p></div><div class="device-card"><div class="board"><span class="trace t1"></span><span class="trace t2"></span><span class="trace t3"></span><div class="chip"></div><div class="meter">DIAGNOSTIKA</div><div class="status">Hľadáme príčinu, nie najdrahší diel</div></div></div></div></header>
<div class="trust"><div class="wrap trust-inner"><div class="trust-item"><strong>Rozumná diagnostika</strong><span>Najprv príčina, potom náklady.</span></div><div class="trust-item"><strong>Individuálne posúdenie</strong><span>Nie všetko sa oplatí opravovať.</span></div><div class="trust-item"><strong>Zvolen a okolie</strong><span>Lokálna dohoda a osobné prevzatie.</span></div><div class="trust-item"><strong>Technika aj IT</strong><span>Od zariadení po webové riešenia.</span></div></div></div>
<section id="sluzby"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Čomu sa venujem</div><h2>Technické problémy bez servisnej omáčky.</h2></div><p>Ku každému problému pristupujem individuálne a riešim hlavne to, čo dáva ekonomický zmysel.</p></div><div class="cards"><article class="card"><div class="icon">⌁</div><h3>Opravy elektroniky</h3><p>Notebooky, drobná elektronika a vybrané domáce zariadenia. Diagnostika poruchy a posúdenie opravy.</p></article><article class="card"><div class="icon">&lt;/&gt;</div><h3>Weby a IT</h3><p>Prezentačné weby, Laravel, WordPress, hosting, domény a riešenie technických problémov.</p></article><article class="card"><div class="icon">◎</div><h3>IoT a malé projekty</h3><p>ESP32, senzory, jednoduché automatizácie a prototypy prepájajúce elektroniku so softvérom.</p></article></div></div></section>
<section class="dark-band" id="ako"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Jednoduchý postup</div><h2>Najprv zistiť. Potom opravovať.</h2></div><p>Ak oprava nedáva zmysel, je lepšie to vedieť skôr než po kúpe dielov.</p></div><div class="steps"><div class="step"><h3>Pošli problém</h3><p>Fotka zariadenia, model a stručne čo sa deje.</p></div><div class="step"><h3>Predbežné posúdenie</h3><p>Povieme si možné príčiny, riziko opravy a či má význam pokračovať.</p></div><div class="step"><h3>Dohoda a riešenie</h3><p>Ak to dáva zmysel, dohodneme prevzatie a ďalší postup.</p></div></div></div></section>
<section id="pristup"><div class="wrap split"><div><div class="eyebrow">Môj prístup</div><h2>Oprava má zmysel len vtedy, keď dáva zmysel aj tebe.</h2><p>Pozerám na cenu zariadenia, pravdepodobnú poruchu, cenu dielov a čas opravy spolu.</p><a class="btn btn-secondary" href="#kontakt">Opýtať sa na konkrétny kus</a></div><div class="list"><div class="list-item"><span class="tick">✓</span><div><strong>Bez automatického menenia dielov</strong><span>Najskôr sa snažíme pochopiť príčinu poruchy.</span></div></div><div class="list-item"><span class="tick">✓</span><div><strong>Ekonomika opravy je súčasť diagnostiky</strong><span>Funkčná oprava za cenu iného zariadenia nie je dobrá oprava.</span></div></div><div class="list-item"><span class="tick">✓</span><div><strong>Aj netypické technické problémy</strong><span>Elektronika, web, hosting alebo IoT sa často prelínajú.</span></div></div><div class="list-item"><span class="tick">✓</span><div><strong>Keď neviem, poviem to</strong><span>Nie každú opravu je rozumné prijať.</span></div></div></div></div></section>
<section id="kontakt" style="padding-top:34px"><div class="wrap"><div class="contact-box"><div><div class="eyebrow">Kontakt</div><h2>Máš niečo pokazené?</h2><p>Najlepšie je začať fotkou, presným modelom a krátkym popisom problému.</p><p class="note">Kontaktné údaje a backend formulára doplníme v ďalšom kroku.</p></div><form onsubmit="event.preventDefault();alert('Formulár zatiaľ nie je napojený.');"><div class="form-row"><input class="field" placeholder="Meno"><input class="field" placeholder="Telefón alebo e-mail"></div><input class="field" placeholder="Zariadenie / model"><textarea class="field" placeholder="Čo nefunguje?"></textarea><button class="btn btn-primary" type="submit">Odoslať dopyt →</button></form></div></div></section>
</main>
